import{_ as a,C as n,o as r,c as i,a2 as t,E as s}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/plot-grid-overview.webp",h="/guide/media/plot-grid-column-menu.webp",l="/guide/media/plot-grid-cell-section.webp",c="/guide/media/plot-grid-change-dialog.webp",g="/guide/media/plot-grid-gauge.webp",v=JSON.parse('{"title":"Plot grid","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plot-grid.md","filePath":"guide/plot-grid.md","lastUpdated":1791657833000}'),u={name:"guide/plot-grid.md"};function p(m,e,w,f,y,b){const o=n("Clip");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="plot-grid" tabindex="-1">Plot grid <a class="header-anchor" href="#plot-grid" aria-label="Permalink to &quot;Plot grid&quot;">​</a></h1><p>The plot grid shows what every thread of the story is doing in every scene. A scene is a row, a thread is a column, and a cell holds what the thread does in that scene, in your own words. You type into the grid the way you type into a spreadsheet, and every cell you write becomes one line of a plain markdown file, <code>StoryThreads.md</code>, that you can open and edit without Leathercase. The grid never writes into your chapters: it keeps its own file of rows, <code>PlotGrid.md</code>, made from the story the first time it is read.</p><p><img src="'+d+`" alt="The plot grid of The Lamp at Ferrol: the state line and the main theme above, scenes down the side grouped by act and chapter, the Time and POV columns, Nora&#39;s arc, and the gauge lane at the right; the subplots lie further right" width="1130" height="852" loading="lazy"></p><h2 id="opening-the-grid" tabindex="-1">Opening the grid <a class="header-anchor" href="#opening-the-grid" aria-label="Permalink to &quot;Opening the grid&quot;">​</a></h2><p>Open a story, then pick <strong>Plot grid</strong> under the story&#39;s name in the sidebar, press <code>Ctrl+4</code> (<code>Cmd+4</code> on macOS), or type &quot;Plot grid&quot; in the command palette (<code>Ctrl/Cmd+K</code>).</p><p>If the story has no scenes and no threads yet, the grid says so: &quot;No scenes yet. A row is a scene, and scenes come from headings in your chapter notes. Write the headings here first, start from a shape someone has already worked out, or write a chapter in your own software.&quot; It offers two ways in, <strong>New scene</strong> and <strong>Start from a template…</strong>, and a link to <a href="/guide/guide/how-a-story-is-read">How this story is read</a> for when you expected scenes and see none.</p><h2 id="the-grid-s-two-files" tabindex="-1">The grid&#39;s two files <a class="header-anchor" href="#the-grid-s-two-files" aria-label="Permalink to &quot;The grid&#39;s two files&quot;">​</a></h2><p>The grid stands on two markdown files in the story&#39;s author data folder (for The Lamp at Ferrol, <code>The Lamp at Ferrol/suite/</code>). Both are yours to read and edit by hand.</p><table tabindex="0"><thead><tr><th>File</th><th>What it holds</th><th>Who changes it</th></tr></thead><tbody><tr><td><code>PlotGrid.md</code></td><td>The rows: acts as <code>#</code> headings, chapters as <code>##</code>, scenes as <code>###</code>, a summary as a comment under a scene. Each row made from your story carries a hidden <code>source:</code> comment linking it to the scene it stands for. A row without one is a planned scene.</td><td>Leathercase writes it from your story the first time; after that, only your actions in the grid change it.</td></tr><tr><td><code>StoryThreads.md</code></td><td>The columns and cells: one <code>##</code> heading per thread, one list line per scene it touches.</td><td>Every cell you write in the grid; and you, by hand.</td></tr></tbody></table><h3 id="the-first-reading" tabindex="-1">The first reading <a class="header-anchor" href="#the-first-reading" aria-label="Permalink to &quot;The first reading&quot;">​</a></h3><p>The first time a story is opened, Leathercase writes <code>PlotGrid.md</code> as a mirror of it: each folder of prose becomes an act, each file read as the story&#39;s prose a chapter, each heading with prose under it a scene, whatever they are called. A file with no headings is one scene. Only files declared as the story&#39;s prose make rows; the cast, plans, research and files nothing claims yet never do (see <a href="/guide/guide/how-a-story-is-read">How a story is read</a>). A summary declared in a chapter&#39;s front matter (<code>summary:</code>, <code>synopsis:</code>, <code>logline:</code> or <code>description:</code>) becomes the row&#39;s summary. Planned scenes from an older <code>Outline.md</code>, in the story&#39;s folder or its <code>suite/</code> folder, are carried in once. <code>Outline.md</code> is read only for this; Leathercase never writes it, and every planned scene from then on goes into <code>PlotGrid.md</code>. The strip under the grid says what happened, for example: &quot;The grid is now its own file, PlotGrid.md: 20 scenes from the story, and 2 planned scenes carried in from the outline. The story&#39;s files are untouched.&quot;</p><p>From then on the grid is yours to arrange. A change in your chapters never rewrites it. When the story and the grid stop agreeing at a row, the row is marked and you decide; see <a href="#when-the-story-changes">When the story changes</a>.</p><h3 id="the-threads-file" tabindex="-1">The threads file <a class="header-anchor" href="#the-threads-file" aria-label="Permalink to &quot;The threads file&quot;">​</a></h3><p><code>StoryThreads.md</code> reads like an outline:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Subplot: The ledger</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[01 The Night the Lamp Went Out#The tower]] — plant: &quot;One prism was cracked.&quot; the page left to be found</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[06 What the Ledger Said#The vestry]] — payoff: the entry read in the mirror</span></span></code></pre></div><p>The link names the scene (file and heading). After the dash comes an optional role (<code>plant:</code>), an optional word from the thread&#39;s scale, an optional quoted sentence from the scene as its anchor, and then your note. A planned scene is linked as <code>[[PlotGrid#Storm]]</code>. If the story&#39;s folder already holds a <code>Story threads.md</code> from Creative Writer at its root (the sample&#39;s Lamp at Ferrol does), Leathercase reads it as the starting point until its own file exists; the first change writes <code>suite/StoryThreads.md</code> and leaves the old file as it was.</p><h2 id="reading-the-grid" tabindex="-1">Reading the grid <a class="header-anchor" href="#reading-the-grid" aria-label="Permalink to &quot;Reading the grid&quot;">​</a></h2><h3 id="rows" tabindex="-1">Rows <a class="header-anchor" href="#rows" aria-label="Permalink to &quot;Rows&quot;">​</a></h3><p>Rows are scenes, in the order of <code>PlotGrid.md</code>. With <strong>Group by chapter</strong> on (the default, in the side column&#39;s <strong>Rows</strong> section), they sit under bands:</p><ul><li><strong>An act band</strong> carries a folder icon and the act&#39;s name. A band over rows that come straight from a folder, not from the grid file, is marked <strong>folder</strong>.</li><li><strong>A chapter band</strong> carries the chapter&#39;s name and its counts, such as &quot;· 2 scenes · 1,240 words&quot;. A chapter of one scene with the same name is drawn as that scene&#39;s row alone.</li></ul><p>Each row begins with the <strong>Scene</strong> cell:</p><ul><li>A thin chip for the scene&#39;s point of view, so the eye&#39;s owner survives a sideways scroll. It is drawn in the colour of characters (or of places, when the POV column names a place), not in a colour of the character&#39;s own, and is grey when the scene has no POV.</li><li>The scene&#39;s name. Click it to open the scene in your writing software, at its heading where the software can go to a line. Double-click it to rename the row. A planned scene&#39;s name is greyed and does not open anything.</li><li>A line under the name: the word count; <strong>planned</strong> for a scene with no prose, a heading you wrote with nothing under it yet included; <strong>from the old outline</strong> for a planned scene carried in from <code>Outline.md</code>; or a change mark (<strong>new in the story</strong>, <strong>gone from the story</strong>, <strong>renamed in the story</strong>).</li><li><code>↕</code> when you moved the row away from its place in the story&#39;s order, and <code>≠</code> where the gauge&#39;s lanes disagree (see <a href="#the-gauge">The gauge</a>).</li><li>A <code>⋯</code> row menu, and an info button on a changed row.</li></ul><p>Then the <strong>Plot</strong> cell: the scene&#39;s summary, or, faint, its first sentence until a summary is written. A planned row with neither shows <strong>summary…</strong>. Double-click to write the summary.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>After Scene and Plot come your threads, one per <code>##</code> heading of <code>StoryThreads.md</code>. The heading&#39;s prefix gives the column its kind, and a coloured stripe on the header repeats it:</p><table tabindex="0"><thead><tr><th>Heading</th><th>Kind</th><th>What it follows</th></tr></thead><tbody><tr><td><code>Arc: [[Nora Vidal]]</code></td><td>Arc</td><td>One character. The header carries the character&#39;s dot.</td></tr><tr><td><code>Theme: What do we owe the drowned?</code></td><td>Theme</td><td>An argument the book makes.</td></tr><tr><td><code>Subplot: The ledger</code></td><td>Subplot</td><td>A line of events.</td></tr><tr><td><code>Kell&#39;s tug</code></td><td>Free thread</td><td>Anything else.</td></tr></tbody></table><p>A prefix that is almost one of these, such as <code>Arcs:</code> or <code>Sub-plot:</code>, is read as a free thread, and a line over the grid says so: &#39;A heading starts with &quot;Arcs:&quot;, which is not Arc, Theme or Subplot; it is read as a plain thread.&#39;</p><p>Columns sit in blocks: <strong>Derived</strong> (the columns with a job, below), then <strong>Arcs</strong>, <strong>Themes</strong>, <strong>Subplots</strong> and <strong>Free</strong>. Each block&#39;s first header carries a small eyebrow with its name and count, such as <strong>Arcs · 1</strong>. Click the eyebrow to fold the block into one narrow column, with a tick in each row where any of its columns has a stop; click again to unfold.</p><p>A column&#39;s header shows its name (double-click to rename), a line of counts such as &quot;4 of 20 · 4 verified · scale of 5&quot;, the theme&#39;s owner when it has one, and the column&#39;s summary under it. A comment line right under the heading in <code>StoryThreads.md</code> is that summary. Double-click it, or the faint <strong>summary…</strong> under a column that has none, to write it in place: <code>Enter</code> saves, <code>Shift+Enter</code> makes a new line, <code>Esc</code> puts it back, and an emptied field takes the line out.</p><p>Scene and Plot stay put while the columns scroll, and so does the header row.</p><p><img src="`+h+'" alt="The ⋯ menu of Kell&#39;s tug open under its header: rename and summary, the three kinds, the four jobs, Set scale, then moving, freezing and hiding the column, each with its command&#39;s name at the right" width="382" height="682" loading="lazy"></p><h3 id="four-columns-with-a-job" tabindex="-1">Four columns with a job <a class="header-anchor" href="#four-columns-with-a-job" aria-label="Permalink to &quot;Four columns with a job&quot;">​</a></h3><p>A column can be given one of four jobs: <strong>POV</strong>, <strong>Time</strong>, <strong>Plot point</strong> or <strong>Main theme</strong>. Use the column&#39;s menu, <strong>Use as POV</strong> and so on; the job is ticked there, and choosing it again takes it off. The job is kept in the story&#39;s declaration, not in your files. When you declare a story whose project note has <code>plot-pov</code>, <code>plot-time</code>, <code>plot-beats</code> or <code>plot-theme</code> in its front matter, Leathercase takes the jobs from there, as it does for The Lamp at Ferrol.</p><ul><li>POV, Time and Plot point move to the <strong>Derived</strong> block after Plot, and their header says <strong>job: POV</strong> and so on.</li><li>The <strong>Main theme</strong> is marked <strong>main</strong> and is read in a line over the grid: <strong>Main theme</strong>, the question, and how many scenes carry it. Themes owned by a character are listed beside it, &quot;from Nora Vidal: …&quot;.</li><li>The Plot point says which beat a scene is at. A template with beats fills it when its rows are applied.</li></ul><p>Nothing is inferred from a name: a column called &quot;Time&quot; that has not been given the job is an ordinary thread.</p><h3 id="cells" tabindex="-1">Cells <a class="header-anchor" href="#cells" aria-label="Permalink to &quot;Cells&quot;">​</a></h3><p>A cell shows the thread&#39;s stop at the scene: the note, or the quoted sentence when there is no note. Before it may come:</p><ul><li>A glyph for the stop&#39;s role. Every thread has four roles: plant ▶, touch (no glyph), payoff ◀, reversal ▼. An arc has four more: want ▸, lie ▹, turn ▼, truth ◂.</li><li>A chip with the word on the column&#39;s scale and its charge, such as <strong>duty 0</strong>, <strong>doubt -1</strong> or <strong>light +2</strong>. The sign is written, so colour is never alone.</li></ul><p><code>+1</code> after the text says the thread has another stop at the same scene. An empty cell shows <code>+</code>.</p><p>A stop&#39;s anchor is checked against the prose every time the story is read:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td>plan</td><td>A stop with no quote: a claim, typed ahead of the draft or from memory of it.</td></tr><tr><td>verified</td><td>A stop whose quote Leathercase found in the scene.</td></tr><tr><td>broken</td><td>A stop whose quote is no longer in the scene: the prose moved. The cell says <strong>anchor no longer in the prose</strong>.</td></tr></tbody></table><h3 id="present-unmoved" tabindex="-1">Present, unmoved <a class="header-anchor" href="#present-unmoved" aria-label="Permalink to &quot;Present, unmoved&quot;">​</a></h3><p>Turn on <strong>Present, unmoved</strong> in the <strong>Rows</strong> section and an arc column marks the scenes where its character is on the page and the arc has no stop, faintly: <strong>present, unmoved</strong>. It is the scene where someone is in the room and nothing happens to them. A column earns the mark only once it holds a verified stop, because on a first draft it would fire everywhere.</p><h3 id="audit-view" tabindex="-1">Audit view <a class="header-anchor" href="#audit-view" aria-label="Permalink to &quot;Audit view&quot;">​</a></h3><p>Press <code>V</code>, or turn on <strong>Audit view</strong> in the <strong>Rows</strong> section, to draw every cell by its state: ◇ plan, ◆ verified, ◈ broken. Headers show the verified count even when it is zero, and the state line reads &quot;40 cells · 12 filled&quot; instead of &quot;12 of 40 filled&quot;. It is a lens over the same grid and is not remembered.</p><h3 id="the-state-line" tabindex="-1">The state line <a class="header-anchor" href="#the-state-line" aria-label="Permalink to &quot;The state line&quot;">​</a></h3><p>The line at the top counts what the grid shows, for example <code>20 scenes · 2 planned · 6 columns · 34 of 120 filled · 30 verified · 1 broken · 1 hidden · 2 gaps</code>. When columns are hidden or blocks folded, a <strong>reset</strong> link beside it shows them all again.</p><h2 id="writing-in-a-cell" tabindex="-1">Writing in a cell <a class="header-anchor" href="#writing-in-a-cell" aria-label="Permalink to &quot;Writing in a cell&quot;">​</a></h2><p>Click a cell to pick it; a thin ring marks it. The arrow keys move from there; <code>Home</code> and <code>End</code> go to the row&#39;s first and last column, <code>Page Up</code> and <code>Page Down</code> ten rows. With nothing picked, the first arrow lands on the first cell.</p><p>To write, press <code>Enter</code> on the picked cell or double-click it. The cell becomes a field with a thicker ring, as a spreadsheet rings the cell being edited, and the strip says only &quot;Editing The ledger at The tower · enter saves · shift+enter a new line · esc puts the line back&quot;: <strong>Undo</strong> and <strong>Redo</strong> leave it until the cell is closed.</p><ul><li><code>Enter</code> saves. Leaving the field saves too, and so does switching view with a key while you type.</li><li><code>Shift+Enter</code> makes a new line.</li><li><code>Esc</code> puts the line back as it was.</li><li>Emptying the field and saving removes the stop.</li></ul><p>The text you type is read the way <code>StoryThreads.md</code> is read: a leading role word and colon (<code>payoff:</code>) sets the role, a scale word and colon sets the word, and a sentence in quotes becomes the anchor. What you do not type keeps the stop&#39;s own: an existing role, word and quote ride above the field as tokens and stay. On a column with a scale, the scale&#39;s words sit under the field as chips; click one to put it in front of the note, or type the start of a word and press <code>Tab</code> to complete it. <code>Tab</code> is otherwise never taken.</p><p>The line lands in <code>StoryThreads.md</code> at once. Writing &quot;she comes back&quot; at The return in the scene Two writes <code>- [[Novel#Two]] — she comes back</code>.</p>',53)),s(o,{name:"plot-grid-write-cell",caption:"Picking a cell, pressing Enter, typing a note and Enter: the strip says Wrote The ledger at The road"}),e[1]||(e[1]=t('<p>To remove a stop, pick the cell and press <code>Delete</code> (or <code>Backspace</code>).</p><h2 id="the-side-column" tabindex="-1">The side column <a class="header-anchor" href="#the-side-column" aria-label="Permalink to &quot;The side column&quot;">​</a></h2><p>The side column (toggle it with <code>Ctrl/Cmd+B</code> or the button at the right of the head) holds sections you can open and close. Each shows its value in its title, so it reads without opening.</p><h3 id="cell" tabindex="-1">Cell <a class="header-anchor" href="#cell" aria-label="Permalink to &quot;Cell&quot;">​</a></h3><p>With nothing picked it says &quot;Pick a cell to write what the thread does in that scene, or press Enter on it to write in place.&quot; With a cell picked, its title shows the state (<strong>plan</strong>, <strong>verified</strong>, <strong>broken</strong>, <strong>empty</strong> or <strong>editing</strong>), and the section edits the same line the cell does:</p><ul><li>A crumb naming the file, the scene, the column and its kind, with <strong>open scene o</strong> to open the scene in your software.</li><li><strong>Role</strong>: the four thread roles, or the eight arc roles under an arc.</li><li><strong>Word on the scale</strong>, on a column with a scale (<strong>none</strong> to clear it); otherwise the cell&#39;s <strong>State</strong>.</li><li><strong>A sentence of the scene that marks it</strong>, the anchor, &quot;quoted as written&quot;. <strong>Pick…</strong> (or <code>&quot;</code> on the grid) lists the scene&#39;s sentences; on a broken stop the sentences nearest the lost quote come first. Clicking one writes it as the anchor straight away. With no prose the list says &quot;No prose to pick from yet.&quot;</li><li><strong>What the thread does here</strong>, the note. While you type in the cell itself, this field follows.</li><li>A line with the state in full, such as &quot;verified · the quote is in the scene&quot;.</li><li><strong>Save stop</strong> writes the line, <strong>Cancel</strong> puts the selection away, and <strong>Remove stop</strong> takes the line out.</li></ul><p><img src="'+l+'" alt="The Cell section for Nora Vidal&#39;s arc at The vestry: role turn, the anchor, the note and Save stop" width="359" height="437" loading="lazy"></p><p>Repairing a broken anchor takes three keys: <code>N</code> walks to the next broken anchor, <code>&quot;</code> lists the sentences, and a click picks one. <code>P</code> walks back.</p><h3 id="columns-1" tabindex="-1">Columns <a class="header-anchor" href="#columns-1" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The title reads &quot;StoryThreads.md · 6&quot;, with the number hidden if any. Every column is listed under its block with its count (&quot;4 of 20&quot;) or its job, and an eye to hide or show it. A hidden column stays hidden, and the state line counts it. What is hidden is kept in <code>GridLayout.json</code> in the story&#39;s <code>suite/</code> folder, so it travels with the story to every computer that opens it.</p><p>Under the list:</p><ul><li><strong>New column</strong>: type a heading and click <strong>Add a column</strong>. Write <code>Arc: [[Nora Vidal]]</code>, <code>Theme: …</code>, <code>Subplot: …</code> or a plain name. It is written to <code>StoryThreads.md</code> as an empty section, ready to fill.</li><li><strong>From a template…</strong> lists the columns the templates offer that the grid does not have yet, grouped by template, with a placeholder arc spelled out once per character. Picking one adds it; a column the template gives a job takes that job.</li><li><strong>Start from a template…</strong> opens the template sheet; see <a href="#templates">Templates</a>.</li></ul><h3 id="rows-1" tabindex="-1">Rows <a class="header-anchor" href="#rows-1" aria-label="Permalink to &quot;Rows&quot;">​</a></h3><p>The title counts the rows and the planned ones. It holds three switches, <strong>Group by chapter</strong>, <strong>Audit view</strong> (<code>v</code>) and <strong>Present, unmoved</strong>, and a field for a scene not written yet: type a title (&quot;A scene not written yet&quot;) and click <strong>Plan a scene</strong>, or leave it empty to plan &quot;New scene&quot;.</p><h3 id="gauge-gaps-and-snapshots" tabindex="-1">Gauge, Gaps and Snapshots <a class="header-anchor" href="#gauge-gaps-and-snapshots" aria-label="Permalink to &quot;Gauge, Gaps and Snapshots&quot;">​</a></h3><p>See <a href="#the-gauge">The gauge</a>, <a href="#gaps">Gaps</a> and <a href="#snapshots">Snapshots</a> below.</p><h2 id="working-with-columns" tabindex="-1">Working with columns <a class="header-anchor" href="#working-with-columns" aria-label="Permalink to &quot;Working with columns&quot;">​</a></h2><p>Every column header has a <code>⋯</code> menu:</p><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Rename…</strong></td><td>Opens a field in the header (or double-click the name). The heading is rewritten in <code>StoryThreads.md</code> and its stops come with it. A column with a job keeps it.</td></tr><tr><td><strong>Summary…</strong> / <strong>Edit the summary…</strong></td><td>Writes the comment line under the heading.</td></tr><tr><td><strong>Make it an arc</strong>, <strong>Make it a theme</strong>, <strong>Make it a subplot</strong>, <strong>Make it a free thread</strong></td><td>Rewrites the heading&#39;s prefix. An arc&#39;s name becomes a link to the character.</td></tr><tr><td><strong>Use as POV</strong>, <strong>Use as Time</strong>, <strong>Use as Main theme</strong>, <strong>Use as Plot point</strong></td><td>Gives the column a job, or takes it off.</td></tr><tr><td><strong>Set scale… (give it a gauge)</strong> / <strong>Set scale…</strong></td><td>Opens the scale sheet.</td></tr><tr><td><strong>Gauge this column</strong></td><td>On a column with a scale: draws it as a gauge lane, or stops.</td></tr><tr><td><strong>Belongs to…</strong></td><td>On a theme other than the main one: gives it an owner.</td></tr><tr><td><strong>Move left</strong>, <strong>Move right</strong></td><td>Moves the column&#39;s block. Time, POV and Plot point each stand alone; arcs, themes, subplots and free threads move as groups. The order is kept in the story&#39;s declaration. Inside a block, columns keep the order of <code>StoryThreads.md</code>.</td></tr><tr><td><strong>Freeze up to here</strong> / <strong>Unfreeze</strong></td><td>Keeps this column and everything left of it in place while the rest scrolls.</td></tr><tr><td><strong>Hide column</strong></td><td>Hides it. The choice is kept in the story&#39;s <code>GridLayout.json</code> and travels with the story.</td></tr><tr><td><strong>Delete column…</strong></td><td>Arms a delete in the header: <strong>Delete Kell&#39;s tug and its 4 stops</strong>, with <strong>Keep</strong> beside it. The heading and every line under it go.</td></tr></tbody></table><h3 id="belongs-to" tabindex="-1">Belongs to <a class="header-anchor" href="#belongs-to" aria-label="Permalink to &quot;Belongs to&quot;">​</a></h3><p>A theme can be the story&#39;s own question or a character&#39;s. <strong>Belongs to…</strong> opens a sheet that explains the difference (&quot;A character theme is the question that character is asking, with a scale of their answers. It is not the arc&quot;), offers an <strong>Owner</strong> list (<strong>The story&#39;s own question</strong>, then the cast), and shows <strong>The heading it writes</strong>, such as <code>## Theme: Is winning worth it? · [[Bastian Kell]]</code>. Only the heading changes; the scale and the stops stay. <strong>Save</strong> writes it.</p><p>The main theme belongs to the story. If its heading names an owner, a line over the grid asks you to take the owner off or choose another main theme.</p><h2 id="working-with-rows" tabindex="-1">Working with rows <a class="header-anchor" href="#working-with-rows" aria-label="Permalink to &quot;Working with rows&quot;">​</a></h2><p>Every row the grid file holds has a <code>⋯</code> row menu. Each item writes <code>PlotGrid.md</code> with Undo; none touches your chapters.</p><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>New scene above</strong>, <strong>New scene below</strong></td><td>Plans a scene, titled &quot;New scene&quot;, next to this one.</td></tr><tr><td><strong>New chapter below</strong></td><td>Plans a chapter after this row&#39;s chapter.</td></tr><tr><td><strong>New act</strong></td><td>Plans an act at the end.</td></tr><tr><td><strong>Rename…</strong></td><td>Renames the row in the grid (or double-click the name). Your chapter&#39;s heading is not changed.</td></tr><tr><td><strong>Summary…</strong></td><td>Writes the row&#39;s summary (or double-click the Plot cell). <code>Enter</code> saves, <code>Esc</code> puts it back; an emptied summary is removed.</td></tr><tr><td><strong>Summary from the scene</strong></td><td>Starts the summary with the scene&#39;s first sentence, for you to edit.</td></tr><tr><td><strong>Move up</strong>, <strong>Move down</strong></td><td>Moves the row. A row moved away from the story&#39;s order is marked <code>↕</code>.</td></tr><tr><td><strong>Put back in the story&#39;s order</strong></td><td>On a moved row: puts it back beside the scenes around it in the story.</td></tr><tr><td><strong>This is a scene I wrote…</strong></td><td>On a planned row, when the story has scenes the grid does not hold yet: links the row to one of them.</td></tr><tr><td><strong>Leave out of the grid</strong></td><td>On a row from your story: the grid stops showing it; the scene stays in your files.</td></tr><tr><td><strong>Delete scene</strong></td><td>On a planned row: deletes it.</td></tr></tbody></table><p>Act and chapter bands have their own menu: <strong>New scene in this chapter</strong> (chapters only), <strong>New chapter below</strong> or <strong>New act</strong>, <strong>Rename…</strong>, <strong>Move up</strong>, <strong>Move down</strong>, and <strong>Delete chapter</strong> or <strong>Delete act</strong>. These act on the grid file, never on your folders.</p><p>The grid&#39;s <code>⋯</code> menu (<strong>Grid menu</strong>) has <strong>New scene</strong>, <strong>New chapter</strong> and <strong>New act</strong> at the end of the grid, plus <strong>Start from a template…</strong>, <strong>Save as template…</strong>, <strong>Show the gauge</strong> or <strong>Hide the gauge</strong>, and <strong>Keep a snapshot</strong>.</p>',27)),s(o,{name:"plot-grid-plan-scene",caption:"New scene above from a row's menu, then renaming the planned row by double-click"}),e[2]||(e[2]=t('<h3 id="linking-a-planned-row-to-a-written-scene" tabindex="-1">Linking a planned row to a written scene <a class="header-anchor" href="#linking-a-planned-row-to-a-written-scene" aria-label="Permalink to &quot;Linking a planned row to a written scene&quot;">​</a></h3><p>When you write a scene you had planned, the grid offers to join them. <strong>This is a scene I wrote…</strong> opens &quot;Which scene of the story is Storm?&quot;, listing the story&#39;s scenes the grid does not hold yet with their files. Pick one and the row takes the scene&#39;s words and anchors; its title and summary stay yours, and the stops written on the planned row move to the scene.</p><h2 id="when-the-story-changes" tabindex="-1">When the story changes <a class="header-anchor" href="#when-the-story-changes" aria-label="Permalink to &quot;When the story changes&quot;">​</a></h2><p>The grid never follows your files by itself. When they stop agreeing at a row, the row is marked and an info button opens a dialog that says why and asks what to do. <strong>Decide later</strong> closes it and leaves the mark.</p><table tabindex="0"><thead><tr><th>Mark</th><th>Dialog</th><th>Choices</th></tr></thead><tbody><tr><td><strong>new in the story</strong></td><td>&quot;The Lens is new in the story. The scene is in Act III - Light/08 The Lens.md but not in the grid. The grid never changes by itself: choose what it becomes.&quot;</td><td><strong>Put it in the grid where the story&#39;s order puts it</strong> (or &quot;…in a new chapter …&quot; when its file is new); <strong>It is the planned scene …</strong> for each planned row it may be; <strong>Leave it out of the grid</strong>; and <strong>Not a scene</strong>, which declares the file&#39;s folder (or the file) as holding notes of a kind or role, so it and later files there never enter the grid.</td></tr><tr><td><strong>gone from the story</strong></td><td>&quot;The row stood for … in …, which the story&#39;s files no longer have.&quot;</td><td><strong>Keep it as a planned scene</strong>, <strong>Remove the row</strong>.</td></tr><tr><td><strong>renamed in the story</strong></td><td>&quot;The row stood for The tower in … The story now has The stair in …, which no row stands for.&quot;</td><td><strong>Follow it: this row is that scene</strong> (its stops follow), <strong>Keep the row as a planned scene</strong>.</td></tr></tbody></table><p><img src="'+c+'" alt="The change dialog for a scene new in the story, with its four choices" width="680" height="444" loading="lazy"></p><h3 id="settling-the-old-outline" tabindex="-1">Settling the old outline <a class="header-anchor" href="#settling-the-old-outline" aria-label="Permalink to &quot;Settling the old outline&quot;">​</a></h3><p>If an older <code>Outline.md</code> planned scenes for a chapter you have since written, they are carried into that chapter and marked <strong>from the old outline</strong>, and the chapter band carries an info button. It opens &quot;The old outline also planned …&quot;: for each carried scene choose <strong>Keep as a planned scene</strong>, <strong>It became …</strong> (one of the written scenes, which takes its stops, and its summary if it has none), or <strong>Drop it</strong>, then <strong>Apply</strong>.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>A template is a starting shape: rows, columns, or both, written as headings. Applying one never writes a word of prose and never calls a model.</p><p><strong>Start from a template…</strong> (grid menu, empty state, or the Columns section) opens a sheet in the side column. It lists the built-in templates and then your own (marked <strong>yours</strong>), each with its counts:</p><table tabindex="0"><thead><tr><th>Template</th><th>Rows</th><th>Columns</th></tr></thead><tbody><tr><td><strong>Three acts</strong></td><td>9 beats in three acts</td><td>Plot point, Theme: Main theme</td></tr><tr><td><strong>Save the Cat</strong></td><td>15 beats</td><td>Plot point, Theme: Main theme, Subplot: B story</td></tr><tr><td><strong>Hero&#39;s journey</strong></td><td>12 beats in Departure, Initiation, Return</td><td>Plot point, Theme: Main theme</td></tr><tr><td><strong>Kishōtenketsu</strong></td><td>4 beats</td><td>Plot point, Theme: Main theme</td></tr><tr><td><strong>An arc per character</strong></td><td>none</td><td>One arc per character in the cast, Theme: Main theme</td></tr><tr><td><strong>Story analysis</strong></td><td>none</td><td>Chapter number, Time, POV, Plot point, Main plot, Theme: Major theme, two subplots, two arcs</td></tr></tbody></table><p>Pick one, then:</p><ul><li><strong>Apply</strong>: <strong>Rows and columns</strong>, <strong>Rows only</strong> or <strong>Columns only</strong> (choices the template lacks are greyed).</li><li><strong>Columns</strong>: a tick per column. A placeholder theme or subplot takes a name of yours; a placeholder arc (Character A) takes a character from the cast; &quot;One arc per character&quot; counts your cast.</li><li>A preview of what will be written, under the ticks: the headings that go to <code>StoryThreads.md</code> (and how many are already there), the scenes that go to <code>PlotGrid.md</code>, and the jobs the columns take.</li></ul><p><strong>Apply</strong> writes it all as one step with Undo. Applying Save the Cat with rows and columns plans fifteen scenes and adds the B story column.</p>',15)),s(o,{name:"plot-grid-template",caption:"Start from a template: choosing Save the Cat, unticking a column, reading the preview, and Apply"}),e[3]||(e[3]=t(`<h3 id="save-as-template" tabindex="-1">Save as template <a class="header-anchor" href="#save-as-template" aria-label="Permalink to &quot;Save as template&quot;">​</a></h3><p><strong>Save as template…</strong> opens a sheet: a <strong>Name</strong> (&quot;Noir in five moves&quot;), and under <strong>Includes</strong>, <strong>Columns, with their jobs</strong> and <strong>Rows, with their summaries and beats</strong>. &quot;Stops and prose are not copied.&quot; <strong>Save</strong> writes a new file under <code>Templates/</code> in the story&#39;s author data folder and says where; a taken name gets a number. Your templates appear in the template sheet and, when they have beats, on the <a href="/guide/guide/beat-board">beat board</a>.</p><h2 id="the-gauge" tabindex="-1">The gauge <a class="header-anchor" href="#the-gauge" aria-label="Permalink to &quot;The gauge&quot;">​</a></h2><p>Every scene turns on a value, and the gauge draws where the story turns. Give a column a <strong>scale</strong>, an odd list of words from most negative to most positive, start its stops with the word the scene mostly is, and the gauge draws the rest. The Lamp at Ferrol&#39;s theme carries one:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Theme: What do we owe the drowned?</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- scale: silence, doubt, duty, witness, light --&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[07 The Storm Rises#The steps]] — duty: &quot;Then it is a candle,&quot; said Inés. the lamp lit without the guild</span></span></code></pre></div><h3 id="setting-a-scale" tabindex="-1">Setting a scale <a class="header-anchor" href="#setting-a-scale" aria-label="Permalink to &quot;Setting a scale&quot;">​</a></h3><p><strong>Set scale…</strong> in the column&#39;s menu opens a sheet. It says which column it is for and how a scale works: &quot;Name the nuances the theme pivots through, from most negative to most positive. The steps are equal; an end that feels heavier gets more words, never a weight.&quot; It lists the words with their charges (−2 to +2 for five words), the middle one marked <strong>neutral</strong>.</p><ul><li><strong>Add a pair</strong> adds a word at each end; <strong>Drop the ends</strong> takes the two ends off. A scale has 3, 5, 7, 9 or 11 words.</li><li>Beside each word, how many cells carry it, or <strong>unused</strong>.</li><li>A word changed in place is a rename: the sheet says how many cells use it (&quot;doubt → unease in 2 cells&quot;), and saving rewrites them.</li><li><strong>What the gauge would count</strong> previews the charged scenes and the inversions, and shows the exact line it will write. A scale that cannot be one says why: an even count, a repeated word, a role word, too few or too many.</li><li><strong>Save scale</strong> writes it with one Undo. <strong>Remove scale</strong> takes the line out.</li></ul><p>A scale line the gauge cannot read is named in the <strong>Gauge</strong> section, &quot;…; fix it with Set scale…&quot;.</p><h3 id="reading-the-lane" tabindex="-1">Reading the lane <a class="header-anchor" href="#reading-the-lane" aria-label="Permalink to &quot;Reading the lane&quot;">​</a></h3><p>When the gauge is shown, its lanes stand at the right edge of the grid. A lane&#39;s header shows the column&#39;s name (or <strong>audience</strong> for the main theme, or the owner), the scale as a row of swatches from red to green, and under it every word of the scale with its charge, such as <code>-1 doubt</code> and <code>+2 light</code>. A word no scene uses yet is faint; point at a word to read how many scenes carry it. Click the swatches or the words to open the scale: change a word there and every cell that carries it follows, in one Undo. Last come the lane&#39;s counts: charged scenes, inversions or turns, unread scenes.</p><p>Each row draws the scene&#39;s charge as pipes either side of a centreline, rose to the left below neutral, green to the right above; a neutral word is a grey tick, and a scene nobody has given a word draws nothing. A line walks down the whole lane, through a point in the middle of each row, however tall the rows grow:</p><ul><li><strong>Running total</strong> (the default) walks the story&#39;s cumulative balance. Where the total changes sign the row carries a diamond and the word <strong>inversion</strong>. When the total outgrows the lane, the header says &quot;line: 1 step = 2&quot;.</li><li><strong>Scene to scene</strong> walks each scene&#39;s own charge, and marks a <strong>turn</strong> where the move changes direction. The line is dashed across a scene with no word.</li></ul><p>A flip at a stop with no quote draws its mark hollow: no line of the prose marks the turn. Two stops at one scene that name different words draw a <code>?</code> and count as unread until you pick one.</p><p><img src="`+g+'" alt="The gauge lane for the main theme, headed audience: the swatches, the pipes of each charged scene, and the running total, which stays below zero in the sample, so the Gauge section reads no inversion" width="565" height="690" loading="lazy"></p><h3 id="the-gauge-section" tabindex="-1">The Gauge section <a class="header-anchor" href="#the-gauge-section" aria-label="Permalink to &quot;The Gauge section&quot;">​</a></h3><p>The section&#39;s title says <strong>no scale yet</strong>, <strong>off</strong>, or how many lanes are drawn. With no scaled column it says &quot;Give a column a scale from its menu, Set scale…, and the gauge draws where the story turns.&quot; Otherwise:</p><ul><li><strong>Show gauge</strong> turns the lanes on or off (also <strong>Show the gauge</strong> / <strong>Hide the gauge</strong> in the grid menu). It is on until you turn it off.</li><li><strong>The line</strong>: <strong>Running total</strong> (&quot;where the story flips&quot;) or <strong>Scene to scene</strong> (&quot;where the move turns&quot;).</li><li><strong>Lanes · 1 of 3</strong>: a switch for each column with a scale. By default the main theme is the lane, else the first scaled column. Three lanes sit side by side at most; untick one to tick another.</li><li><strong>What the gauge counted</strong>: per lane, the charged scenes, the unread ones, and where it flips; how many flips no line marks; and, with two lanes or more, where they disagree, by pair (&quot;audience vs Nora Vidal: 2&quot;).</li></ul><p>Rows where two lanes carry opposite signs get <code>≠</code> on the scene, with the odd lane&#39;s initial when one stands apart. Signs only: scales of different lengths do not compare in size. <code>N</code> and <code>P</code> also walk to the flips no quote marks.</p><h2 id="gaps" tabindex="-1">Gaps <a class="header-anchor" href="#gaps" aria-label="Permalink to &quot;Gaps&quot;">​</a></h2><p>The <strong>Gaps</strong> section lists what the grid can count for itself, with no model: a column with a stop in fewer than a quarter of the written scenes (once eight scenes are written), and a character on the page for three scenes or more in a row while their arc says nothing. Each reads, for example, &quot;Kell&#39;s tug has a stop in 4 of 20 written scenes.&quot; or &quot;Nora Vidal is on the page in 3 scenes in a row, The hall to The yard, and the arc has no stop there.&quot;, with <strong>Show</strong>, which picks the first cell it points at. The state line counts them. With none it says &quot;Nothing the grid can point at&quot;. Findings, not judgements: what to do about them is yours.</p><h2 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h2><p><strong>Keep a snapshot</strong> in the grid menu keeps today&#39;s grid as machine data, a file <code>PlotGrid 2026-10-06.json</code> in the story&#39;s <code>suite/snapshots/</code> folder; a second snapshot on the same day replaces the first. Once one exists, a row of tabs sits over the grid: <strong>Now</strong>, then one tab per snapshot, newest first, named by its day (&quot;6 Oct&quot;). A snapshot tab draws the grid as it stood, read only: chapter bands, scenes with their counts, each cell as text with ✓ for verified and ✗ for broken. The state line counts it and ends in <strong>read only</strong>. Two tabs apart are the outline against the draft.</p><p>The <strong>Snapshots</strong> section lists them with their counts; click a day to open its tab, again to go back to Now. With none it says &quot;None yet. A snapshot keeps today&#39;s grid as machine data, to set beside a later one.&quot;</p><h2 id="what-else-the-grid-writes" tabindex="-1">What else the grid writes <a class="header-anchor" href="#what-else-the-grid-writes" aria-label="Permalink to &quot;What else the grid writes&quot;">​</a></h2><p>What the grid knows about a character, an event or a theme is copied into a note Leathercase keeps for it in the author data folder: an arc into <code>Characters/Nora Vidal.md</code>, a subplot into <code>Events/The ledger.md</code>, a theme into <code>Notes/What do we owe the drowned.md</code>. The copy sits between two <code>suite:grid</code> marks under the heading &quot;From the plot grid&quot;; everything outside the marks is yours. The POV column only names a character and writes nothing. <code>StoryThreads.md</code> stays the one source: change a stop there or in the grid, not in the copy. If the marks in a note are broken, or writing the section would touch your text, the grid leaves the note as it is and the strip names it. These notes are what the <a href="/guide/guide/characters">character sheet</a> and the <a href="/guide/guide/graph">Graph</a> read.</p><p>How the grid is laid out (hidden columns, folded blocks, the frozen column, the switches, the gauge&#39;s lanes and line) is kept in <code>GridLayout.json</code> in the story&#39;s <code>suite/</code> folder. Column jobs and block order are kept in the story&#39;s declaration, <code>Story.json</code>. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="undo" tabindex="-1">Undo <a class="header-anchor" href="#undo" aria-label="Permalink to &quot;Undo&quot;">​</a></h2><p>Under the grid runs a strip. Before anything is written it says &quot;Click a cell and press Enter to write in it.&quot; After each write it names it, such as <strong>Wrote The ledger at The road</strong>, <strong>Planned a scene above The tower</strong>, <strong>Applied Save the Cat: 3 columns, 15 scenes</strong> or <strong>Set the scale of …: …</strong>, with <strong>Undo</strong>, the stack&#39;s depth (&quot;ctrl+z · 3 in the stack&quot;), and <strong>Redo</strong> when something was undone.</p><p><code>Ctrl/Cmd+Z</code> undoes and <code>Ctrl/Cmd+Shift+Z</code> redoes, outside a text field. Undo puts the file back whole; a step that wrote two files (a template, a planned row linked to a scene) puts both back together. If a file changed outside Leathercase since, nothing is written and the strip says &quot;The file changed outside Leathercase since; nothing was written, and the step was dropped.&quot; <code>Enter</code> and <code>Delete</code> on a button belong to the button, so pressing them on <strong>Undo</strong> never edits a cell.</p><h2 id="proposals-from-agents" tabindex="-1">Proposals from agents <a class="header-anchor" href="#proposals-from-agents" aria-label="Permalink to &quot;Proposals from agents&quot;">​</a></h2><p>An agent you connected with <strong>Lay out</strong> can propose planned rows in the chapter and part they belong to, a summary for each row, columns with their kind, a line about them and a scale, and cells rated on that scale with the sentence that shows them. With the assistant&#39;s layer on (<code>Ctrl/Cmd+.</code>), what it proposed shows dashed beside your own, until you accept or dismiss it. <strong>Review in Plot grid</strong>, on a changeset in the inbox, opens the grid with a review bar beside it.</p><p>A row title, a summary, a column or a cell you accepted from an agent is drawn on a light grey wash: generated. Point at it to read it whole and to see which agent laid it out. The mark goes the first time you edit the text, here or in another editor. See <a href="/guide/guide/inbox#what-an-agent-laid-out-stays-marked">Proposals and the inbox</a>.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td><td>Move between cells</td></tr><tr><td><code>Home</code> <code>End</code></td><td>First, last column</td></tr><tr><td><code>Page Up</code> <code>Page Down</code></td><td>Ten rows</td></tr><tr><td><code>Enter</code></td><td>Write in the cell. Writing: <code>Enter</code> saves, <code>Shift+Enter</code> a new line, <code>Esc</code> puts the line back</td></tr><tr><td><code>Esc</code></td><td>Put the selection away</td></tr><tr><td><code>Delete</code></td><td>Remove the stop</td></tr><tr><td><code>&quot;</code></td><td>Anchor: pick a sentence of the scene</td></tr><tr><td><code>N</code> <code>P</code></td><td>Next, previous broken anchor or unmarked flip</td></tr><tr><td><code>O</code></td><td>Open the scene in your writing software</td></tr><tr><td><code>V</code></td><td>Audit view</td></tr><tr><td><code>Ctrl/Cmd+Z</code>, <code>Ctrl/Cmd+Shift+Z</code></td><td>Undo, redo</td></tr><tr><td><code>?</code></td><td>Show the keys</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/beat-board">Beat board</a>, where scenes start as cards</li><li><a href="/guide/guide/threads">Threads</a>, the same threads drawn as a chart</li><li><a href="/guide/guide/characters">Characters</a>, where an arc&#39;s stops show on the character sheet</li><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a>, for how chapters and scenes are found</li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',37))])}const q=a(u,[["render",p]]);export{v as __pageData,q as default};
